from pathlib import Path
import shutil

CATEGORIES = {
    'Images': ['.jpg', '.png', '.gif'],
    'Docs': ['.pdf', '.txt', '.docx'],
    'Code': ['.py', '.js', '.html'],
}

source = Path('Downloads')
for file in source.iterdir():
    if file.is_file():
        ext = file.suffix.lower()
        for cat, exts in CATEGORIES.items():
            if ext in exts:
                dest = source / cat
                dest.mkdir(exist_ok=True)
                shutil.move(str(file), str(dest))
                print(f'{file.name} -> {cat}/')
